const grammarPointFor = (category: Question["category"], tags: string[]): Question["grammarPoint"] => {
  if (tags.some((tag) => tag.includes("doing") || tag.includes("to do") || tag.includes("宾语"))) return "non-finite";
  if (category === "confusable") return "non-finite";
  if (category === "preposition" || category === "fixed-collocation") return "prepositions-collocations";
  return "verb-pattern";
};

const questions: Question[] = rows.map(([id, phrase, sentence, answer, translation, explanation, distractors, tags, category, type]) => {
  const texts = [answer, ...distractors];
  const hash = [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0);
  const offset = hash % texts.length;
  const ordered = texts.slice(offset).concat(texts.slice(0, offset));
  const options = ordered.map((text, i) => ({ id: String.fromCharCode(65 + i), text }));
  const answerOption = options.find((option) => option.text === answer)!;
  return { id: `q-${id}`, category, type: type ?? "choice", prompt: sentence, options, answer: type === "input" ? answer : answerOption.id, acceptedAnswers: [answer], collocation: phrase, translation, explanation, tags, difficulty: "basic", grammarPoint: grammarPointFor(category, tags) };
});

export { questions };
